<?php
require __DIR__.'/../src/bootstrap.php';$user=requireLogin();$error='';
$points=Store::all('sales_points');if($user['role']==='sales_user')$points=array_values(array_filter($points,fn($p)=>canAccessSalesPoint($user,(int)$p['id'])));$warehouses=allowedWarehouses($user);$items=Store::indexed('items');$batches=array_filter(Store::all('batches'),fn($b)=>$b['active']);
if($_SERVER['REQUEST_METHOD']==='POST'){requirePost();try{$lines=[];$batchIds=listField($_POST,'batch_id');$qtys=listField($_POST,'qty');foreach($batchIds as $i=>$batch){$b=Store::find('batches',(int)$batch);if($b)$lines[]=['item_id'=>$b['item_id'],'batch_id'=>(int)$batch,'qty'=>(int)($qtys[$i]??0)];}$id=SalesOrderService::createDraft($user,(int)$_POST['sales_point_id'],(int)$_POST['warehouse_id'],$lines,field($_POST,'request_key'),field($_POST,'note'));flash('Đã tạo đơn phân phối.');redirect('/sales-order.php?id='.$id);}catch(DomainException $e){$error=ERROR_LABELS[$e->getMessage()]??'Không tạo được đơn phân phối. Kiểm tra kho, điểm bán và số lượng.';}catch(Throwable $e){error_log('Sales order create failed: '.$e->getMessage());$error='Không tạo được đơn phân phối. Vui lòng thử lại.';}}
$orders=Store::all('sales_orders');$scope=array_column($warehouses,'id');$orders=array_filter($orders,fn($o)=>in_array($o['warehouse_id'],$scope,true)||canAccessSalesPoint($user,$o['sales_point_id']));$title='Đơn phân phối';$active='sales-orders';require __DIR__.'/../templates/header.php';
?>
<header class="page-head"><div><h1>Đơn phân phối</h1><p>Đơn hàng từ kho địa điểm đến đại lý, cửa hàng và siêu thị.</p></div></header>
<?php if($error):?><div class="error-summary" role="alert"><?=e($error)?></div><?php endif;?>
<section class="card"><h2>Tạo đơn</h2><form method="post" class="form"><?=csrfInput()?><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-row"><?php if($user['role']!=='sales_user'):?><label class="form-field">Kho xuất<select name="warehouse_id" required><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['code'].' · '.$w['name'])?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="warehouse_id" value="0"><?php endif;?><label class="form-field">Điểm bán<select name="sales_point_id" required><?php foreach($points as $p):if(!$p['active'])continue;?><option value="<?=$p['id']?>"><?=e($p['code'].' · '.$p['name'])?></option><?php endforeach;?></select></label><label class="form-field form-field--wide">Ghi chú<input name="note" maxlength="255"></label></div><table class="table table--form"><thead><tr><th>Lô</th><th>Số lượng</th></tr></thead><tbody><?php for($i=0;$i<3;$i++):?><tr><td><select name="batch_id[]"><option value="">— Chọn lô —</option><?php foreach($batches as $b):?><option value="<?=$b['id']?>"><?=e($b['code'].' · '.($items[$b['item_id']]['name']??''))?></option><?php endforeach;?></select></td><td><input type="number" min="1" name="qty[]" value=""></td></tr><?php endfor;?></tbody></table><button class="button">Tạo đơn chờ xử lý</button></form></section>
<section class="card table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Kho</th><th>Điểm bán</th><th>Trạng thái</th><th>Ngày tạo</th></tr></thead><tbody><?php foreach($orders as $o):$p=Store::find('sales_points',$o['sales_point_id']);?><tr><td><a class="text-link" href="/sales-order.php?id=<?=$o['id']?>"><?=e($o['code'])?></a></td><td><?=e(warehouseName($o['warehouse_id']))?></td><td><?=e($p['name']??'—')?></td><td><?=e($o['status'])?></td><td><?=e(dateOnly($o['created_at']))?></td></tr><?php endforeach;?></tbody></table></section>
